def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    result = []
    current_char = texto[0]
    count = 1
    for char in texto[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1
    result.append(f"{current_char}{count}")
    return "".join(result)

def iniciales(nombre: str) -> str:
    # Split the string by any whitespace, ignoring leading/trailing spaces
    # and treating hyphens as part of words (they are not separators)
    words = nombre.split()
    # Take the first character of each word, convert to uppercase, and join
    return ''.join(word[0].upper() for word in words if word)

def es_palindromo(texto: str) -> bool:
    s = [c.lower() for c in texto if c.isalnum()]
    return s == s[::-1]

def aplanar(datos: list) -> list:
    result = []
    for item in datos:
        if isinstance(item, (list, tuple)):
            result.extend(aplanar(item))
        else:
            result.append(item)
    return result

import csv
from io import StringIO

def parsear_ventas(texto: str) -> list[dict]:
    # Convert string to StringIO to use csv.reader
    reader = csv.reader(StringIO(texto))
    rows = list(reader)

    # If no rows, return empty list
    if not rows:
        return []

    # Check header
    header = rows[0]
    if header != ['fecha', 'producto', 'cantidad', 'precio']:
        raise ValueError

    result = []
    for row in rows[1:]:
        # Skip rows that are empty (no fields)
        if not row:
            continue

        # Check that we have exactly 4 fields
        if len(row) != 4:
            raise ValueError

        try:
            cantidad = int(row[2])
        except ValueError:
            raise ValueError
        if cantidad < 0:
            raise ValueError

        try:
            precio = float(row[3])
        except ValueError:
            raise ValueError

        result.append({
            'fecha': row[0],
            'producto': row[1],
            'cantidad': cantidad,
            'precio': precio
        })

    return result

import re

def parsear_fecha(texto: str) -> str:
    texto = texto.strip()

    # Mapeo de meses en español
    meses = {
        'enero': 1, 'febrero': 2, 'marzo': 3, 'abril': 4,
        'mayo': 5, 'junio': 6, 'julio': 7, 'agosto': 8,
        'septiembre': 9, 'octubre': 10, 'noviembre': 11, 'diciembre': 12
    }

    # Regla de aniversario
    def es_leap(año):
        return (año % 4 == 0 and año % 100 != 0) or (año % 400 == 0)

    # Lista de días máximos por mes
    max_dias = [31, 29 if es_leap(año) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    # 1. Formato AAAA-MM-DD
    match1 = re.fullmatch(r'\d{4}-\d{2}-\d{2}', texto)
    if match1:
        año, mes, día = map(int, texto.split('-'))
        if 1 <= mes <= 12 and 1 <= día <= max_dias[mes-1]:
            return f"{año}-{mes:02d}-{día:02d}"

    # 2. Formato DD/MM/AAAA
    match2 = re.fullmatch(r'\d{2}/\d{2}/\d{4}', texto)
    if match2:
        día, mes, año = map(int, texto.split('/'))
        if 1 <= mes <= 12 and 1 <= día <= max_dias[mes-1]:
            return f"{año}-{mes:02d}-{día:02d}"

    # 3. Formato D de MES de AAAA
    parts = texto.split()
    if len(parts) == 5 and parts[0].isdigit() and parts[2] in meses:
        día_str, mes_str, año_str = parts[0], parts[2], parts[4]
        día = int(día_str)
        mes = meses[mes_str.lower()]
        año = int(año_str)
        if 1 <= día <= max_dias[mes-1]:
            return f"{año}-{mes:02d}-{día:02d}"

    raise ValueError("Formato no aceptado o fecha inválida")

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

def mochila(pesos: list[int], valores: list[int], capacidad: int) -> tuple[int, list[int]]:
    if len(pesos) != len(valores):
        raise ValueError("Lengths of pesos and valores must be equal")
    if capacidad < 0:
        raise ValueError("Capacidad must be non-negative")
    for p in pesos:
        if p < 0:
            raise ValueError("Pesos must be non-negative")

    n = len(pesos)
    if n == 0:
        return (0, [])

    # Initialize DP: for each weight from 0 to capacidad, store the best solution (value, count, indices)
    dp = [None] * (capacidad + 1)
    dp[0] = (0, 0, [])

    # Process each item
    for i in range(n):
        w_i = pesos[i]
        v_i = valores[i]
        # Update dp from high to low to ensure 0/1 knapsack
        for w in range(capacidad, w_i - 1, -1):
            if dp[w - w_i] is not None:
                prev_val, prev_count, prev_indices = dp[w - w_i]
                candidate_val = prev_val + v_i
                candidate_count = prev_count + 1
                candidate_indices = prev_indices + [i]
                # Compare with existing dp[w] using the tie-breaking rules
                current = dp[w]
                if current is None or is_better(candidate_val, candidate_count, candidate_indices, current[0], current[1], current[2]):
                    dp[w] = (candidate_val, candidate_count, candidate_indices)

    # Find the best solution among all weights
    best_val = -1
    best_count = float('inf')
    best_indices = []

    for w in range(capacidad + 1):
        if dp[w] is not None:
            val, count, indices = dp[w]
            # Compare with current best using tie-breaking
            if val > best_val:
                best_val = val
                best_count = count
                best_indices = indices
            elif val == best_val:
                if w < w + best_indices[0]:
                    best_val = val
                    best_count = count
                    best_indices = indices
                elif w == w + best_indices[0]:
                    if count < best_count:
                        best_count = count
                        best_indices = indices
                    elif count == best_count:
                        if indices < best_indices:
                            best_indices = indices
    return (best_val, best_indices)


def is_better(val1, count1, indices1, val2, count2, indices2):
    if val1 > val2:
        return True
    if val1 < val2:
        return False
    if count1 < count2:
        return True
    if count1 > count2:
        return False
    return indices1 < indices2

def evaluar(expresion: str) -> int:
    # Tokenizer
    def tokenize(s):
        i, n = 0, len(s)
        tokens = []
        while i < n:
            ch = s[i]
            if ch == ' ':
                i += 1
                continue
            elif ch.isdigit():
                start = i
                while i < n and s[i].isdigit():
                    i += 1
                tokens.append(s[start:i])
            elif ch == '+':
                tokens.append('+')
                i += 1
            elif ch == '-':
                tokens.append('-')
                i += 1
            elif ch == '*':
                tokens.append('*')
                i += 1
            elif ch == '/':
                raise ValueError("Operator '/' not allowed")
            elif ch == '//':
                if i + 1 < n and s[i + 1] == '/':
                    tokens.append('//')
                    i += 2
                else:
                    raise ValueError("Invalid // operator")
            elif ch == '(':
                tokens.append('(')
                i += 1
            elif ch == ')':
                tokens.append(')')
                i += 1
            else:
                raise ValueError("Invalid character")
        # Check for '**'
        for j in range(n - 1):
            if s[j] == '**' and j + 2 < n:
                raise ValueError("Invalid ** operator")
        return tokens

    tokens = tokenize(expresion)
    if not tokens:
        raise ValueError("Empty expression")

    # Recursive descent parser
    idx = 0
    n = len(tokens)

    def parse_expression():
        nonlocal idx
        val, idx = parse_term()
        while idx < n and tokens[idx] in ('+', '-'):
            op = tokens[idx]
            idx += 1
            next_val, idx = parse_term()
            if op == '+':
                val = val + next_val
            else:
                val = val - next_val
            idx += 1
        return val, idx

    def parse_term():
        nonlocal idx
        val, idx = parse_factor()
        while idx < n and tokens[idx] in ('*', '//'):
            op = tokens[idx]
            idx += 1
            next_val, idx = parse_factor()
            if op == '*':
                val = val * next_val
            else:
                if next_val == 0:
                    raise ZeroDivisionError("Division by zero")
                val = val // next_val
            idx += 1
        return val, idx

    def parse_factor():
        nonlocal idx
        if tokens[idx] == '(':
            idx += 1
            val, idx = parse_expression()
            if tokens[idx] != ')':
                raise ValueError("Missing closing parenthesis")
            idx += 1
            return val, idx
        elif tokens[idx] == '-':
            idx += 1
            val, idx = parse_factor()
            return -val, idx
        elif tokens[idx] == '+':
            raise ValueError("Unary plus not allowed")
        else:
            if tokens[idx].isdigit():
                return int(tokens[idx]), idx + 1
            else:
                raise ValueError("Expected number or parenthesis")

    result, _ = parse_expression()
    if idx != n:
        raise ValueError("Extra tokens")
    return result

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("La capacidad de la caché debe ser no negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave in self._datos:
            # Move the accessed key to the end to mark as recently used
            self._datos.move_to_end(clave)
            return self._datos[clave]
        return None

    def put(self, clave, valor):
        # If the key already exists, update it and mark as recently used
        if clave in self._datos:
            self._datos.move_to_end(clave)
            self._datos[clave] = valor
            return

        # If the cache is full (capacity == 0), don't store anything
        if self.capacidad > 0 and len(self._datos) >= self.capacidad:
            # Evict the least recently used item
            self._datos.popitem(last=False)

        # Insert the new key-value pair
        self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
